import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import 'package:zan/Core/Storage/Remote/api_error_handler.dart';import 'package:zan/Features/client/Service/Carpenter/data/Models/get_all_services_model.dart';import '../../data/repositories/carpenter_services_repo.dart';import '../../data/sources/carpenter_services_sources.dart';class CarpenterServicesRepoImpl extends CarpenterServicesRepo{  @override  Future<Either<Failure, List<GetAllServicesModel>>> getAllServices() async{    try {      final response = await CarpenterServicesSources.getAllServices();      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }}